// === Inspired by 'Recursivesquarepacking' by 'Roni Kaufman' ===
// Created as variant #3 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

let compo;
let toAdd = [];

const N = 24;
let u;

let palette = ["#abcd5e", "#29ac9f", "#14976b", "#b3dce0", "#62b6de", "#2b67af", "#f589a3", "#ef562f", "#fc8405", "#f9d531"];

function setup() {
	createCanvas(504, 504);
	frameRate(30);
	u = width/N;
	noStroke();

	initCompo();
}

function draw() {
  // === Variant 3: Fractal Orbit Matrix ===
  gridOffset = noise(frameCount * 0.01) * 80;
  push();
  translate(gridOffset, -gridOffset);

	if (toAdd.length == 0) {
		compo.sort((el1, el2) => (el2.s-el1.s));
		let idx = 0, el = compo[idx];
		while (el.children.length > 0) {
			el = compo[idx];
			idx++;
		}

		if (el.s > 1 || !el.parent) {
			// create children
			let newSquares = squarePacking(el.i, el.i+el.s, el.j, el.j+el.s, el.s-1, 500);
			for (let squ of newSquares) {
				let newEl = squ;
				newEl.parent = el;
				newEl.children = [];
				toAdd.push(newEl);
			}
			shuffle(toAdd, true);
			//toAdd.sort((el1, el2) => (el1.s-el2.s));
			//toAdd.sort((el1, el2) => (el2.j+el2.s/2-el1.j-el1.s/2));
			el.children = [...toAdd];
			compo.push(...toAdd);
		} else {
			// restore everything
			initCompo();
		}
	}

	let n = ceil(sqrt(toAdd.length)/2);
	for (let i = 0; i < n; i++) {
		let el = toAdd.pop();
		let x = el.i*u, y = el.j*u, s = el.s*u;
		if (el.s == 1) fill(["#fffbe6", "#050505"][(el.i+el.j)%2]);
		else fill(random(palette));
		square(x, y, s);
	}

  pop();
}

function initCompo() {
	compo = [{
		i: 0,
		j: 0,
		s: N,
		parent: undefined,
		children: []
	}];
	background(random(palette));
}

function squarePacking(iMin, iMax, jMin, jMax, sMax, nSquares) {
	let squares = [];

	for (let i = 0; i < nSquares; i++) {
    let newSqu = generateSquare(squares, iMin, iMax, jMin, jMax, sMax);
    if (newSqu.s > 2 || (newSqu.s > 1 && random() < 1/2)) { // avoid 2x2 squares, forbid 1x1 squares
      squares.push(newSqu);
    }
  }

	for (let i = iMin; i < iMax; i++) {
		for (let j = jMin; j < jMax; j++) {
			let newSqu = {
				i: i,
				j: j,
				s: 1
			}
			let canAdd = true;
			for (let squ of squares) {
				if (squaresIntersect(newSqu, squ)) {
					canAdd = false;
					break;
				}
			}
			if (canAdd) {
				squares.push(newSqu);
			}
		}
	}

	return squares;
}

function squaresIntersect(squ1, squ2) {
	return ((squ1.i <= squ2.i && squ1.i+squ1.s > squ2.i) || (squ2.i <= squ1.i && squ2.i+squ2.s > squ1.i)) && ((squ1.j <= squ2.j && squ1.j+squ1.s > squ2.j) || (squ2.j <= squ1.j && squ2.j+squ2.s > squ1.j));
}

function generateSquare(squares, iMin, iMax, jMin, jMax, sMax) {
  let i = ~~random(iMin, iMax);
  let j = ~~random(jMin, jMax);

	// determine biggest possible size
	let s;
	if (squares.length == 0) {
		s = min(iMax-i, jMax-j, sMax);
	} else {
		s = biggestPossibleSize(squares, iMax, jMax, sMax, i, j);
	}

  let squ = {
    i: i,
    j: j,
    s: s
  };
  return squ;
}

function biggestPossibleSize(squares, iMax, jMax, sMax, i, j) {
	let s = 1;
	let intersects = false;
	while (!intersects) {
		s++;
		for (let squ of squares) {
			if (i+s > iMax || j+s > jMax || s > sMax || squaresIntersect({i: i, j: j, s: s}, squ)) {
				intersects = true;
				break;
			}
		}
	}
	return s-1;
}

